import math

import rclpy
from rclpy.node import Node
from sensor_msgs.msg import LaserScan


class Forward(Node):
    def __init__(self):
        super().__init__('forward_watch')
        self.sub = self.create_subscription(LaserScan, 'scan', self.on_scan, 10)

    def on_scan(self, msg):
        index = int((0.0 - msg.angle_min) / msg.angle_increment)
        if index < 0 or index >= len(msg.ranges):
            self.get_logger().warn('forward beam outside the sweep')
            return
        distance = msg.ranges[index]
        if not math.isfinite(distance):
            self.get_logger().warn('no return on the forward beam', throttle_duration_sec=2.0)
            return
        self.get_logger().info('{:.2f} m ahead in frame {}'.format(distance, msg.header.frame_id))


def main():
    rclpy.init()
    node = Forward()
    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    finally:
        node.destroy_node()
        if rclpy.ok():
            rclpy.shutdown()


if __name__ == '__main__':
    main()

