import rclpy
from example_interfaces.srv import AddTwoInts
from rclpy.node import Node
from sensor_msgs.msg import LaserScan


class Coordinator(Node):
    def __init__(self):
        super().__init__('coordinator')
        self.client = self.create_client(AddTwoInts, 'add_two_ints')
        self.sub = self.create_subscription(LaserScan, 'scan', self.on_scan, 10)

    def on_scan(self, msg):
        if not self.client.service_is_ready():
            return
        request = AddTwoInts.Request()
        request.a = len(msg.ranges)
        request.b = 1
        future = self.client.call_async(request)
        future.add_done_callback(self.on_reply)

    def on_reply(self, future):
        result = future.result()
        if result is None:
            self.get_logger().error('the adder failed to answer')
            return
        self.get_logger().info('beams plus one is {}'.format(result.sum))


def main():
    rclpy.init()
    node = Coordinator()
    try:
